StructuredTextModel.Text:
//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//	NAME:					HE_NodeStat_NX_EIC202
//	CREATOR:				Helgevold - Ruben Byman
// REQUIREMENTS: NX-EIC202 RIO Node
//
// DESCRIPTION: 	Collects status information from node and outputs alarm
//								
//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
// VERSION LOG:
//	VERSION			DATE					SIGN							DESCRIPTION
//	1.0.0					2026-04-28			Ruben Byman				Initial release
//	
//================================================================================================================================

(*************************************************************************
 *	PERFORMING LOGIC
 *************************************************************************)

//Comm check
Wrk_CommFault := HE_CommFault(PORT:=Cfg_EIP_Interface, IP:=Cfg_NodeIP);

//Status word
HE_NXEIC202_Status(Inp_Status:= INT_TO_WORD(Inp_EIC_Status), 
									Sts_Observation=>Wrk_Observation, 
									Sts_MinorFault=>Wrk_MinorFault, 
									Sts_PartialFault=>Wrk_PartialFault, 
									Sts_MajorFault=>Wrk_MajorFault, 
									Sts_CommonError=>Wrk_CommonError, 
									Sts_IORefreshing=>Wrk_IORefresh);

(*************************************************************************
 *	UPDATING VARIABELS
 *************************************************************************)
 	
Ext_DigitalValue.EXT_General.LocationIndex[0]:=Cfg_MainLocation; //First index / main location is forced; remaining tree optional can be set in SCADA

FB_DigitalValue_Logic.Inp_AlmSuppress:=			FALSE;	//Not in use
FB_DigitalValue_Logic.Inp_AlmSuppressDesc:=	'';	//Not in use
FB_DigitalValue_Logic.Cfg_ControlCabinet:=		Cfg_ControlCabinet;
FB_DigitalValue_Logic.Cfg_ControllerTAG:=		Cfg_ControllerTAG;
FB_DigitalValue_Logic.Inp_ModuleFault:=			Wrk_CommFault;
FB_DigitalValue_Logic.Cfg_ProcessTAG:=			Cfg_ProcessTAG;

FB_DigitalValue_Logic.Inp_Value1:=				Wrk_Observation;
FB_DigitalValue_Logic.Inp_Value1_Suffix:=		'Observation fault';
FB_DigitalValue_Logic.Inp_Value2:=				Wrk_MinorFault;
FB_DigitalValue_Logic.Inp_Value2_Suffix:=		'Minor fault';
FB_DigitalValue_Logic.Inp_Value3:=				Wrk_PartialFault;
FB_DigitalValue_Logic.Inp_Value3_Suffix:=		'Partial fault';
FB_DigitalValue_Logic.Inp_Value4:=				Wrk_MajorFault;
FB_DigitalValue_Logic.Inp_Value4_Suffix:=		'Major fault';
FB_DigitalValue_Logic.Inp_Value5:=				NOT Wrk_IORefresh;
FB_DigitalValue_Logic.Inp_Value5_Suffix:=		'IO refreshing stopped';
FB_DigitalValue_Logic.Inp_Value6:=				FALSE;
FB_DigitalValue_Logic.Inp_Value6_Suffix:=		'';
FB_DigitalValue_Logic.Inp_Value7:=				FALSE;
FB_DigitalValue_Logic.Inp_Value7_Suffix:=		'';
FB_DigitalValue_Logic.Inp_Value8:=				FALSE;
FB_DigitalValue_Logic.Inp_Value8_Suffix:=		'';
FB_DigitalValue_Logic.Inp_Value9:=				FALSE;
FB_DigitalValue_Logic.Inp_Value9_Suffix:=		'';

(*************************************************************************
 *	EXCECUTING LOGIC BLOCK
 *************************************************************************)

FB_DigitalValue_Logic(ENS:=TRUE, 
										Ext_DigitalValue:=Ext_DigitalValue, 
										Int_Alarm:=Int_Alarm);

(*************************************************************************
 *	UPDATING OUTPUS
 *************************************************************************)
 
Sts_Alarm:=						FB_DigitalValue_Logic.Sts_AlarmTriggered;
Out_CommFault := 			Wrk_CommFault;
